def regular(path): path = Path(path) require(not any(p.is_symlink() for p in (path, *path.parents)), 'symlink_refused') require(path.is_file() and path.stat().st_size <= LIMIT, 'missing_or_oversize_file') return path.read_bytes()
def _relative(name): require(type(name) is str and name and '\\' not in name, 'unsafe_member') p = PurePosixPath(name) require(not p.is_absolute() and all(x not in ('', '.', '..') for x in name.split('/')), 'unsafe_member') return name
def load_pinned_directory_v01(root, expected_sha256, *, portable=True): """The independent expected identity is mandatory and checked before JSON.""" require(type(expected_sha256) is str and re.fullmatch('[0-9a-f]{64}', expected_sha256), 'external_pin_required') root = Path(root) body = regular(root/'MANIFEST.json') require(sha(body) == expected_sha256, 'external_pin_mismatch') manifest = strict(body) require(type(manifest) is dict and type(manifest.get('files')) is list, 'manifest_shape') if portable: require(set(manifest) == {'version', 'files'} and manifest['version'] == VERSION, 'manifest_version') files = {} folded = set() for item in manifest['files']: require(set(item) == {'path', 'bytes', 'sha256', 'mode'}, 'manifest_row_shape') name = _relative(item['path']) require(name != 'MANIFEST.json' and name.casefold() not in folded, 'duplicate_member') folded.add(name.casefold()) raw = regular(root/name) require(len(raw) == item['bytes'] and sha(raw) == item['sha256'], 'member_identity:'+name) require(item['mode'] in ('0400', '0600', '0644', '0755') and format((root/name).stat().st_mode & 0o7777, '04o') == item['mode'], 'member_mode:'+name) files[name] = raw actual = set() for p in root.rglob('*'): require(not p.is_symlink(), 'symlink_refused') if p.is_file(): actual.add(p.relative_to(root).as_posix()) require(actual == set(files) | {'MANIFEST.json'}, 'unmanifested_or_missing_member') return files
