def export_v01(source, expected_source_sha256, semantics, expected_semantics_sha256, target): """Export exact saved data plus an explicit derived source-location map.""" w4 = load_pinned_directory_v01(source, expected_source_sha256, portable=False) w3 = load_pinned_directory_v01(semantics, expected_semantics_sha256) files, modes, mapping = {}, {}, [] for origin, values, prefix, pin in ((Path(source), w4, 'w4/', expected_source_sha256), (Path(semantics), w3, 'w3/', expected_semantics_sha256)): for name, raw in values.items(): selected = name.startswith('snapshot/') if prefix == 'w4/' else name.startswith('story/') if not selected: continue destination = prefix + (name.removeprefix('snapshot/') if prefix == 'w4/' else name) files[destination] = raw modes[destination] = format((origin/name).stat().st_mode & 0o7777, '04o') mapping.append(dict(path=destination, source_member=name, source_manifest_sha256=pin, sha256=sha(raw), transformation='EXACT_BYTES_RELOCATED')) source_map = dict(version=VERSION, classification='DERIVED_LOCATION_PROJECTION_ORIGINAL_BYTES_PRESERVED', w4_manifest_sha256=expected_source_sha256, w3_manifest_sha256=expected_semantics_sha256, synthetic=True, no_provider_attestation=True, files=sorted(mapping, key=lambda r:r['path'])) files['source_map.json'] = canonical(source_map) # Validate before producing an exported package; no collection on omissions. verify_material_v01(files) return dict(status='EXPORTED', expected_manifest_sha256=_write_package(target, files, modes), independent_review='PIN_MUST_BE_SUPPLIED_OUTSIDE_PACKAGE', new_external_calls=0)
