def _root_record(run, prefix, value): from . import native_contracts_v01 as c result, incoming = run['root_result'], run['root_input'] require(result['decision'] == 'ACCEPT' and result['selected_candidate_id'] == c.identity(prefix, value), 'recorded_root_candidate') require(result['decision_input_id'] == incoming['decision_input_id'], 'recorded_root_input') require(result['target_root_id'] == incoming['target_root_id'] and result['transaction_id'] == incoming['transaction_id'], 'recorded_root_scope') require(not result['permission_created'] and not result['effect_requested'], 'recorded_root_nonpermission')
def _work_chain(run, material, output, names, sample_report=None): from . import native_contracts_v01 as c, math_v01 as maths require(run['material'] == material and run['output'] == output, 'performed_material_output') require(run['semantic_proposal']['payload'] == material, 'performed_semantic_payload') items, results = run['program']['candidate']['items'], run['results'] require([r['work_id'] for r in results] == [i['work_id'] for i in items] == names, 'performed_work_set') previous = material for i, (item, result) in enumerate(zip(items, results)): require(result['status'] == 'COMPLETED', 'performed_work_status') require(strict(result['invocation']['inputs'][0]['value']) == previous, 'performed_parent_value') if i: require(item['inputs'][0]['source'] == dict(predecessor_work_id=names[i-1], output_field='material', expected_type='TEXT'), 'performed_parent_binding') require(bool(result['consumed_fields']), 'performed_consumption_missing') actual = strict(result['result']['output'][0]['value']) if names[i] == 'review': expected = dict(previous, requirements_checked=c.problem_from_material(material).content_id, contradiction=[]) elif names[i] == 'compile': expected = dict(previous, optimization=maths.compile_optimization_v01(c.problem_from_material(material),material['profile']).to_plain_v01()) elif names[i] == 'qpu_prepare': expected = dict(previous, safe_output=output) elif names[i] == 'qpu_validate': expected = dict(previous, sample_validation=sample_report) else: require(names[i] == 'qpu_consume' and sample_report is not None, 'supported_work_kind') expected = dict(previous, safe_output=output, assignment=output['assignment'], validation=sample_report['selected']['validation']) require(actual == expected, 'performed_intermediate_output:'+names[i]) previous = actual require(previous['safe_output'] == output, 'performed_final_output') _root_record(run, 'wedding_result', output) require(run['root_input']['target_root_id'] == material['problem']['owner_root_id'] and run['root_input']['transaction_id'] == 'transaction:'+material['request_ref'], 'performed_root_scope') require(run['owner']['request_ref'] == material['request_ref'] and run['owner']['problem'] == material['problem'] and run['owner']['profile'] == material['profile'], 'performed_owner') return previous
def _semantic_story(files, original): from . import semantic_adapter_v01 as s, native_contracts_v01 as c, supplied_v01 as supplied, math_v01 as maths results, runs = {}, {} for key in ('A', 'B', 'VERIFY', 'AMBIGUOUS', 'SR1', 'SR2', 'SR3'): x = _json(files, f'w3/story/{key}_intake.json') records = _json(files, f'w3/story/{key}_captures.json') actual = _json(files, f'w3/story/{key}.json') candidates = [c.canonical(x['current'])] if x['current'] == strict(original): candidates.append(original) current = next((v for v in candidates if c.digest(v) == records[0]['source_snapshot']), None) require(current is not None, 'semantic_source_snapshot') i = s.LiveIntakeV01(original, current, x['request_ref'], x['safe_intent'], tuple(x['permitted_tasks']), tuple(x['permitted_profiles']), x['structural_disclosure'], tuple(x['amendment_guests']), (), None if x['prior_output'] is None else c.canonical(x['prior_output']), x['prior_result_ref']) owner, expected = s.accepted_material_v01(i, records, origin=actual['material']['origin']) if expected['revision_acknowledgement']: decision = actual['material']['revision_root'] require(decision['decision'] == 'ACCEPT' and decision['selected_candidate_id'] == c.identity('revision', expected['revision_acknowledgement']), 'semantic_revision_review') expected['revision_root'] = decision if owner.task_kind == 'VALIDATE_EXISTING': prior = next((v for v in runs.values() if v['artifact']['artifact_id'] == i.prior_result_ref), None) require(prior is not None and i.prior_output_bytes == c.canonical(prior['output']) and prior['material']['problem'] == actual['material']['problem'], 'semantic_prior_result') expected.update(assignment=prior['output']['assignment'], existing_result_ref=i.prior_result_ref) require(expected == actual['material'], 'semantic_to_performed_material:'+key) if owner.task_kind == 'CLARIFY': require(actual['status'] == 'NEEDS_CLARIFICATION' and expected['profile'] is None, 'semantic_clarification') results[key] = dict(status='NEEDS_CLARIFICATION', profile=None, questions=actual['questions']) continue supplied.validate_saved_run_v01(actual, owner=owner) require(actual['semantic_proposal']['payload'] == expected, 'semantic_proposal_binding') require(records[0]['capture_ref'] in c.canonical(actual['source_context']).decode(), 'semantic_BSEP_binding') runs[key] = actual results[key] = dict(status='PASS', output=actual['output'], captures=[r['capture_ref'] for r in records]) require(maths.validate_assignment_v01(s._problem(c.canonical(runs['SR2']['owner']['problem'])), runs['SR1']['output']['assignment'], runs['SR2']['owner']['profile']).to_plain_v01()['status'] != 'VALID', 'revision_old_plan_not_invalidated') return results
def verify_material_v01(files): """Finite saved relations. Does not deserialize Host or execute native Work.""" from . import native_contracts_v01 as c, qpu_contracts_v01 as q, qpu_application_v01 as app from . import qpu_bridge_v01 as bridge, qpu_output_v01 as display mapping = _json(files, 'source_map.json') require(mapping['version'] == VERSION and mapping['synthetic'] is True, 'source_map_version') require({r['path'] for r in mapping['files']} == set(files)-{'source_map.json'}, 'source_map_coverage') for item in mapping['files']: require(item['transformation'] == 'EXACT_BYTES_RELOCATED' and sha(files[item['path']]) == item['sha256'], 'source_map_identity') installed = Path(__file__).resolve().parents[3] for path, raw in files.items(): if path.startswith('w4/candidate/hedgehog/') and path.endswith('.py'): require(regular(installed/path.removeprefix('w4/candidate/')) == raw, 'installed_source_identity:'+path) original = files['w4/candidate/fixtures/wedding_seating/reference_problem_v01.json'] require(regular(installed/'fixtures/wedding_seating/reference_problem_v01.json') == original, 'installed_original_fixture') story = _semantic_story(files, original) scope = _json(files, 'w4/operator_scope.json') ledger = _json(files, 'w4/provider/ledger.json') require(len(ledger['attempts']) == 2 and {r['profile'] for r in ledger['attempts']} == set(q.PROFILES), 'hardware_profile_inventory') require(len({r['client_token'] for r in ledger['attempts']}) == 2 and sum(r['reserved_microusd'] for r in ledger['attempts']) <= 1450000, 'hardware_task_allowance') rows = [] for row in ledger['attempts']: profile = row['profile']; key = 'A' if profile == q.PROFILES[0] else 'B' original_prep = _json(files, f'w4/native/{profile}/prepare.json') intake = _json(files, f'w4/basis_w3/story/{key}_intake.json') captures = _json(files, f'w4/basis_w3/story/{key}_captures.json') require(intake == _json(files, f'w3/story/{key}_intake.json') and captures == _json(files, f'w3/story/{key}_captures.json'), 'hardware_semantic_story_binding') _, material = app.preparation_material_v01(intake, captures, files[f'w4/basis_w1/captures/{profile}/grid.json'], request_ref=original_prep['material']['request_ref'], original_bytes=original) numeric = _json(files, f'w4/numeric/{profile}/numeric.json') q.check_numeric_v01(material, numeric) bridge.check_request_v01(row['request'], scope=scope, material=material, numeric=numeric, token=row['client_token']) require(c.digest(row['request']) == row['request_sha256'], 'hardware_request_hash') require(strict(row['actual_wire']) == row['request'] and c.digest(row['actual_wire'].encode()) == row['actual_wire_sha256'], 'hardware_actual_wire') _work_chain(original_prep, material, numeric, ['review', 'compile', 'qpu_prepare']) approval = row['approval']; claim = dict(request=row['request'], scope=scope, expires=approval['expires']) require(approval['request_sha256'] == row['request_sha256'] and approval['scope'] == scope and approval['native_prepare_result_ref'] == original_prep['artifact']['artifact_id'], 'submission_preparation_binding') _root_record(approval, 'wedding_qpu_request', claim) require(approval['root_input']['target_root_id'] == material['problem']['owner_root_id'] and approval['root_input']['transaction_id'] == 'transaction:'+material['request_ref'], 'submission_root_scope') require(datetime.fromisoformat(row['submitting']).timestamp() < approval['expires'], 'submission_approval_time') meta = row['metadata']; raw_bytes = files['w4/provider/'+_relative(row['raw_path'])]; raw = strict(raw_bytes); tm = raw['taskMetadata'] require(row['state'] == 'VALIDATED_AND_SAVED' and meta['status'] == tm['status'] == 'COMPLETED', 'hardware_completed_state') require(meta['quantumTaskArn'] == tm['id'] == row['task_arn'], 'hardware_task_binding') require(meta['deviceArn'] == tm['deviceId'] == row['request']['deviceArn'] == scope['device_arn'], 'hardware_device_binding') require(meta['shots'] == tm['shots'] == row['request']['shots'] == 1000 and row['network_attempts'] == 1, 'hardware_shot_attempt_binding') require(raw['additionalMetadata']['action'] == strict(row['request']['action']), 'hardware_returned_action') require(meta['outputS3Bucket'] == row['request']['outputS3Bucket'] == scope['bucket'] and row['result_key'] == meta['outputS3Directory']+'/results.json' and meta['outputS3Directory'].startswith(row['request']['outputS3KeyPrefix']), 'hardware_S3_binding') for field in ('createdAt', 'endedAt'): require(datetime.fromisoformat(meta[field].replace('Z','+00:00')) == datetime.fromisoformat(tm[field].replace('Z','+00:00')), 'hardware_metadata_time') require(c.digest(raw_bytes) == row['raw_sha256'], 'hardware_raw_identity') report = q.samples_v01(material, numeric, raw_bytes, task_arn=row['task_arn'], allow_suboptimal=scope['feasible_suboptimal_allowed']) require(report == _json(files, f'w4/provider/{profile}_sample_validation.json'), 'hardware_sample_lineage') require(report['selected'] is not None, 'hardware_no_feasible_sample') # Nonnegative pair objective plus a feasible zero witness justifies 0 for # this installed original fixture; no search or supplied oracle is used. require(report['selected']['validation']['components']['objective'] == 0 and report['local_reference_objective'] == report['objective_gap'] == 0, 'supported_zero_reference') resume_names = [p for p in files if p.startswith(f'w4/native/{profile}/resume_prepare_') and p.endswith('.json')] require(len(resume_names) == 1, 'resume_preparation_inventory') resumed = _json(files, resume_names[0]) _work_chain(resumed, material, numeric, ['review', 'compile', 'qpu_prepare']) consumed = _json(files, f'w4/native/{profile}/consume.json'); cm = consumed['material'] require(cm['prepare_material'] == material and cm['numeric_parent'] == numeric and cm['prepare_output_sha256'] == c.digest(numeric), 'consumed_preparation_material') require(cm['prepare_result_ref'] == resumed['artifact']['artifact_id'] == consumed['owner']['parent_ref'] and cm['prepare