ral['not_before_satisfied'] and consumed['now'] <= recorded < claim['expires'], 'save_recorded_event_time') require(incoming['target_root_id'] == material['problem']['owner_root_id'] and incoming['transaction_id'] == 'transaction:'+cm['request_ref'], 'save_recorded_owner') rows.append(dict(profile=profile, task_arn=row['task_arn'], status='RECORDED_COMPLETED_CONSUMED_SAVED', raw_sha256=row['raw_sha256'], measurements=report['successful_shots'], valid=report['valid_samples'], invalid=report['invalid_samples'], distinct=report['distinct_valid_plans'], selected=expected, gap=report['objective_gap'], consumed_result_ref=row['consumed_result_ref'], save_claims=[s['claim'] for s in saves])) return dict(version=VERSION, status='PASS', classification='SAFE_DERIVED_SAVED_RELATIONSHIPS_AT_RECORDED_EVENT_TIMES', hardware=rows, semantics=story, unsupported=['FULL_NATIVE_SCHEMA_REPLAY','PROVIDER_CRYPTOGRAPHIC_ATTESTATION','CURRENT_PERMISSION','ARBITRARY_FIXTURES_OR_SUBOPTIMAL_REFERENCE'], operations=dict(network=0,models=0,qpu=0,Root=0,Host=0,D=0,Work=0,search=0,effects=0,DRS_writes=0))
