def repin(tmp_path, files): """Reach semantic predicates under an explicitly test-supplied coherent pin.""" files = dict(files) mapping = p.strict(files['source_map.json']) mapping['files'] = [r for r in mapping['files'] if r['path'] in files] for row in mapping['files']: row['sha256'] = p.sha(files[row['path']]) files['source_map.json'] = p.canonical(mapping) return p._write_package(tmp_path,files,{})
def changed(files, member, change): value=p.strict(files[member]);change(value);files[member]=p.canonical(value)
