er(x): x['output']['assignment']=[0]*12 x['root_result']['selected_candidate_id']='wedding_result:'+p.sha(p.canonical(x['output'])) last=p.strict(x['results'][-1]['result']['output'][0]['value']);last['safe_output']=x['output'] x['results'][-1]['result']['output'][0]['value']=p.canonical(last).decode() changed(files,f'w4/native/{profile}/consume.json',alter) elif case=='save': def alter(x): items=dict(x[0]['root_input']['post_vv_bundle']['items']) items.update(required_evidence_refs=['work_results:foreign'],provided_evidence_refs=['work_results:foreign']) x[0]['root_input']['post_vv_bundle']['items']=list(items.items()) changed(files,f'w4/outputs/{profile}/save_receipts.json',alter) elif case=='time': def alter(x): x[0]['claim']['expires']=0 x[0]['root_result']['selected_candidate_id']='wedding_save:'+p.sha(p.canonical(x[0]['claim'])) changed(files,f'w4/outputs/{profile}/save_receipts.json',alter) elif case=='device': changed(files,'w4/provider/ledger.json',lambda x:x['attempts'][0]['metadata'].update(deviceArn='arn:foreign')) elif case=='parent': def alter(x): x['material']['prepare_result_ref']='work_results:foreign';x['owner']['parent_ref']='work_results:foreign' changed(files,f'w4/native/{profile}/consume.json',alter) elif case in ('root','submission_root'): def alter_root(x): for field in ('root_input','root_result'): x[field].update(target_root_id='organizer:foreign',transaction_id='transaction:foreign') if case=='root': changed(files,f'w4/native/{profile}/consume.json',alter_root) else: changed(files,'w4/provider/ledger.json',lambda x:alter_root(x['attempts'][0]['approval'])) else: del files[f'w4/provider/{profile}_results.json'] test_pin=repin(tmp_path/'TEST_ONLY_COHERENT',files) with pytest.raises(ValueError,match=reason):p.verify_v01(tmp_path/'TEST_ONLY_COHERENT',test_pin) assert p.sha((root/'MANIFEST.json').read_bytes())==pin
